#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_ARGS   65          /* inclusive of program name */
#define MAX_LEN    1024        /* maximum allowed length of any argument */

int main(int argc, char *argv[])
{
    /* 1. Too many arguments */
    if (argc > MAX_ARGS) {
        puts("TOO_MANY");
        return 0;
    }

    /* 2. No strings to compare */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* 3. Check length of each argument */
    for (int i = 1; i < argc; ++i) {
        if ((size_t)strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* 4. Compute longest common prefix */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && first[j] == s[j]) {
            ++j;
        }
        prefix_len = j;               /* shrink to the common part */
        if (prefix_len == 0) {
            break;                    /* no common prefix any more */
        }
    }

    if (prefix_len == 0) {
        puts("EMPTY");
    } else {
        char *out = (char *)malloc(prefix_len + 1);
        if (!out) {
            return 0;
        }
        memcpy(out, first, prefix_len);
        out[prefix_len] = '\0';
        puts(out);
        free(out);
    }

    return 0;
}
